const sb = () => { const c = clienteBanco(); if (!c) throw new Error('Banco indisponível. Recarregue o sistema.'); return c; };

async function chamar(body) {
  /* v249: manda a organização aberta (o Provedor em Modo Suporte não tem organização própria). */
  const { data, error } = await sb().functions.invoke(FUNCAO, { body: { ...body, orgId: sessao.orgId?.() || undefined } });
  if (error) {
    let msg = error.message, codigo = '', status = error.context?.status || 0;
    try { const c = await error.context?.json?.(); if (c?.error) msg = c.error; if (c?.codigo) codigo = c.codigo; } catch { /* ok */ }
    const e = new Error(msg || 'O Laudomiro não respondeu.'); e.codigo = codigo; e.status = status; throw e;
  }
  if (data?.error) { const e = new Error(data.error); e.codigo = data.codigo || ''; throw e; }
  return data;
}

/* Pede para a própria tela se redesenhar quando uma chamada termina —
   só se a pessoa ainda estiver nela. */
function repintar() {
  const h = (location.hash || '').replace('#', '').split('?')[0];
  if (h && !/^(laudomiro|campo-agentes)/.test(h)) return;
  window.GRID?.tratarAcao?.('campo:lq-pintar');
}

async function carregarStatus() {
  if (_statusCarregando) return;
  _statusCarregando = true;
  try { _status = await chamar({ acao: 'status' }); }
  catch (e) {
    /* Função ainda não publicada (404) ou sem módulo: a tela fica no modo "em configuração". */
    _status = { configurado: false, falha: e.message, restantes: null, recentes: [] };
  }
  finally { _statusCarregando = false; repintar(); }
}

function saudacao() {
  const h = new Date().getHours();
  const nome = (sessao.usuario()?.nome || '').trim().split(/\s+/)[0];
  return `${h < 12 ? 'Bom dia' : h < 18 ? 'Boa tarde' : 'Boa noite'}${nome ? ', ' + esc(nome) : ''}.`;
}

/* ── Pedaços da tela ───────────────────────────────────────────────────── */
/* v250: o Laudomiro é uma permissão do perfil de acesso. Sem ela, a aba Perguntar fica travada
   (as Fichas continuam). O servidor também recusa — isto aqui só evita a pessoa tentar à toa. */
function semPermissao() {
  // v251: o servidor sabe se a empresa liberou o perfil padrão; enquanto a resposta não chega, vale o perfil personalizado
  if (_status && typeof _status.permitido === 'boolean') return !_status.permitido;
  const p = typeof window._permAtual === 'function' ? window._permAtual() : null;
  return !!p && !(p.acoes || {}).usar_laudomiro;
}

function abas() {
  const n = L.AGENTES.length;
  const cota = _aba === 'perguntar' && !semPermissao() && _status?.configurado && _status.restantes != null
    ? `<span class="lq-cota-t"><b>${_status.restantes}</b> ${_status.restantes === 1 ? 'pergunta restante' : 'perguntas restantes'} em ${esc(_status.mes || 'este mês')}</span>` : '';
  const nova = _aba === 'perguntar' && _conv.length ? '<button type="button" class="btn btn-outline btn-sm" data-acao="campo:lq-nova">Nova conversa</button>' : '';
  return `<div class="lq-topo">
    <div class="lq-id"><span class="lq-seal">${SEAL}</span><div><b>Laudomiro</b><small>Engenheiro de segurança do GRID</small></div></div>
    <div class="lq-abas" role="tablist" aria-label="Laudomiro">
      <button type="button" role="tab" aria-selected="${_aba === 'perguntar'}" class="${_aba === 'perguntar' ? 'on' : ''}" data-acao="campo:lq-aba:perguntar">${IC.perg}<span>Perguntar</span></button>
      <button type="button" role="tab" aria-selected="${_aba === 'fichas'}" class="${_aba === 'fichas' ? 'on' : ''}" data-acao="campo:lq-aba:fichas">${IC.fichas}<span>Fichas<span class="lq-ab-x"> dos agentes</span></span><i>${n}</i></button>
    </div>
    <div class="lq-cota">${cota}${nova}</div>
  </div>`;
}

function compositor({ grande = false } = {}) {
  const bloq = semPermissao();
  const off = (_status && !_status.configurado) || bloq;
  const ocupado = _conv.some(t => t.carregando);
  const anx = !off && anexosLigados();
  const ph = bloq ? 'Seu perfil de acesso não inclui o Laudomiro' : off ? 'O Laudomiro está sendo configurado'
    : _anexo ? (_anexo.tipo === 'fds' ? 'O que você quer saber deste produto? (opcional)' : 'O que você quer saber desta foto? (opcional)')
      : _ctx ? 'Pergunte mais sobre este produto' : 'Pergunte ao Laudomiro';
  return `<div class="lq-comp-w">${anx && _menuAnexo ? menuAnexo() : ''}
    ${_ctx && !_anexo ? `<span class="lq-ctx">${IC.pdf}<span>Conversando sobre: <b>${esc(_ctx.produto)}</b></span><button type="button" data-acao="campo:lq-ctx-sair" aria-label="Parar de conversar sobre este produto">${I.x}</button></span>` : ''}
    ${anx ? chipAnexo() : ''}
    <div class="lq-comp${grande ? ' grande' : ''}${off ? ' off' : ''}${anx ? ' com-clip' : ''}">
      ${anx ? `<button type="button" class="lq-clip${_menuAnexo || _anexo ? ' on' : ''}" data-acao="campo:lq-clip" aria-label="Anexar FDS ou foto" aria-expanded="${_menuAnexo}">${IC.clip}</button>` : ''}
      <input type="text" id="lqTxt" data-cp="lq.txt" data-cp-enter="lq.enviar" value="${esc(_txt)}" maxlength="1000" autocomplete="off"
        placeholder="${ph}" aria-label="Sua pergunta" ${off ? 'disabled' : ''}>
      <button type="button" class="lq-env" data-acao="campo:lq-enviar" aria-label="Enviar pergunta" ${off || ocupado ? 'disabled' : ''}>${SEND}</button>
    </div></div>
    <div class="lq-priv">${_anexo ? 'O arquivo não fica guardado no GRID: só a resposta. Não envie foto com rosto ou nome de trabalhador.' : 'Não escreva nome, CPF nem dados de trabalhadores.'}</div>`;
}

function inicio() {
  const bloq = semPermissao();
  const off = (_status && !_status.configurado) || bloq;
  const rec = (_status?.recentes || []).slice(0, 5);
  return `<section class="lq-ini">
    <h2 class="lq-h">${saudacao()} O que você precisa resolver?</h2>
    <p class="lq-sub">Pergunte como perguntaria a um engenheiro de segurança. Ele responde com o item da norma.</p>
    ${bloq ? `<div class="lq-conf">${I.info}<div><b>Seu perfil de acesso não inclui perguntas ao Laudomiro.</b> Peça ao administrador da sua empresa para liberar (Configurações → Laudomiro). As <button type="button" class="lq-lnk" data-acao="campo:lq-aba:fichas">Fichas dos agentes</button> continuam disponíveis.</div></div>` : off ? `<div class="lq-conf">${I.info}<div><b>O Laudomiro está sendo configurado.</b> Logo você poderá perguntar aqui. Enquanto isso, as <button type="button" class="lq-lnk" data-acao="campo:lq-aba:fichas">Fichas dos agentes</button> continuam funcionando.</div></div>` : ''}
    ${compositor({ grande: true })}
    ${anexosLigados() && !_anexo ? `<div class="lq-atalhos"><label><input type="file" hidden accept="application/pdf,.pdf" data-cp-foto="lq.fds">${IC.pdf}<span>Ler uma FDS (FISPQ)</span></label><label><input type="file" hidden accept="image/jpeg,image/png,image/webp,image/*" data-cp-foto="lq.galeria">${IC.cam}<span>Analisar uma foto</span></label></div>` : ''}
    <div class="lq-sug">${SUGESTOES.map(([r, p], i) => `<button type="button" class="lq-cd" data-acao="campo:lq-sug:${i}" ${off ? 'disabled' : ''}><small>${r}</small><b>${esc(p)}</b></button>`).join('')}</div>
    ${rec.length ? `<div class="lq-rec"><h4>Conversas recentes</h4>${rec.map(r => `<button type="button" data-acao="campo:lq-abrir:${esc(r.id)}"><span>${r.tipo === 'fds' ? `<i class="lq-rt fds">FDS</i>${esc(r.pergunta.replace(/^FDS:\s*/, ''))}` : r.tipo === 'foto' ? `<i class="lq-rt foto">FOTO</i>${esc(r.pergunta.replace(/^Foto:\s*/, ''))}` : esc(r.pergunta)}</span><small>${esc(quando(r.criado_em))}</small></button>`).join('')}</div>` : ''}
  </section>`;
}

function quando(iso) {
  if (!iso) return '';
  const d = new Date(iso), hoje = new Date();
  if (d.toDateString() === hoje.toDateString()) return 'hoje';
  return d.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' });
}

/* {{n}} → botão com o rótulo do trecho; **negrito** simples. */
function textoComRefs(texto, turno, tIdx) {
  const mapa = new Map((turno.trechos || []).map(t => [t.n, t]));
  const vistos = new Set();   // v249: a mesma fonte aparece uma vez por parágrafo
  return esc(texto).replace(/\*\*(.+?)\*\*/g, '<b>$1</b>').replace(/\s*\{\{(\d+)\}\}/g, (m, n) => {
    const t = mapa.get(+n); if (!t || vistos.has(+n)) return '';
    vistos.add(+n);
    const on = _painel && _painel.t === tIdx && _painel.n === +n;
    return ` <button type="button" class="lq-it${on ? ' on' : ''}" data-acao="campo:lq-fonte:${tIdx}.${+n}" title="Ver o texto: ${esc(t.fonte)}">${esc(t.rotulo)}</button>`;
  })
    // v252: citação repetida tirada não deixa "()" ou "( , )" sobrando
    .replace(/\(\s*(?:,\s*)*\)/g, '')
    .replace(/\(\s*,\s*/g, '(').replace(/\s*,\s*\)/g, ')')
    .replace(/\s+([.,;:])/g, '$1');
}

function tipoFonte(t) { return t.tipo === 'oficial' ? 'Texto oficial' : 'Ficha do Laudomiro'; }

function resposta(turno, tIdx) {
  if (turno.carregando && turno.anexo) return carregandoAnexo(turno);
  if (turno.aviso) return avisoAnexo(turno);
  if (turno.resposta?.tipo === 'fds' && !turno.erro) return respostaFds(turno, tIdx);
  if (turno.resposta?.tipo === 'foto' && !turno.erro) return respostaFoto(turno, tIdx);
  if (turno.carregando) return `<article class="lq-resp lq-carr" aria-live="polite"><span class="lq-seal p">${SEAL}</span><div><b>Consultando as normas…</b><small>Buscando os itens que respondem a sua pergunta.</small></div></article>`;
  if (turno.erro) return `<article class="lq-resp lq-falha">${IC.erro}<div><b>${esc(turno.erro)}</b>${turno.podeRepetir ? `<button type="button" class="btn btn-outline btn-sm" data-acao="campo:lq-repetir:${tIdx}">Tentar de novo</button>` : ''}</div></article>`;
  const r = turno.resposta; if (!r) return '';
  const [vt, vc] = VEREDITO[r.veredito] || VEREDITO.INFO;
  const fontes = (turno.trechos || []).filter(t => (r.fontes || []).includes(t.n));
  return `<article class="lq-resp">
    <header class="lq-ver"><span class="lq-selo ${vc}">${vt}</span><div><h3>${esc(r.titulo)}</h3>${r.subtitulo ? `<p>${esc(r.subtitulo)}</p>` : ''}</div></header>
    <div class="lq-txt">${(r.resposta || []).map(p => `<p>${textoComRefs(p, turno, tIdx)}</p>`).join('')}</div>
    ${r.cuidado ? `<div class="lq-cuid">${IC.erro}<div><b>Cuidado:</b> ${textoComRefs(r.cuidado, turno, tIdx)}</div></div>` : ''}
    ${fontes.length ? `<div class="lq-fontes">${fontes.slice(0, 4).map(t => `<button type="button" class="lq-fo" data-acao="campo:lq-fonte:${tIdx}.${t.n}"><small>${tipoFonte(t)}</small><b>${esc(t.rotulo)}</b></button>`).join('')}</div>` : ''}
    <footer class="lq-acts">
      <button type="button" data-acao="campo:lq-copiar:${tIdx}">${IC.copiar}<span>Copiar</span></button>
      ${turno.id ? `<button type="button" class="${turno.nota === 'util' ? 'on' : ''}" data-acao="campo:lq-util:${tIdx}" aria-pressed="${turno.nota === 'util'}">${IC.util}<span>Útil</span></button>
      <button type="button" class="${turno.nota === 'erro' ? 'on' : ''}" data-acao="campo:lq-erro:${tIdx}">${IC.erro}<span>Tem erro</span></button>` : ''}
      <small>Indicação para o técnico. Não substitui laudo.</small>
    </footer>
  </article>`;
}

function conversa() {
  const balao = (t) => t.anexo
    ? `<div class="lq-eu"><span><em class="anx">${t.anexo.tipo === 'fds' ? IC.pdf : IC.cam}${esc(t.anexo.nome || '')}</em>${esc(t.pergunta || (t.anexo.tipo === 'fds' ? 'Ler esta FDS' : 'Quais pontos de atenção você vê aqui?'))}</span></div>`
    : `<div class="lq-eu"><span>${esc(t.pergunta)}</span></div>`;
  return `<div class="lq-fio">${_conv.map((t, i) => `${balao(t)}${resposta(t, i)}`).join('')}</div>
    <div class="lq-comp-fixo">${compositor()}</div>`;
}

function limparMd(x) {
  return String(x || '').replace(/<!--[\s\S]*?-->/g, '').replace(/^.*não substitui o publicado no DOU.*$/gim, '')
    .split('\n').map(l => l.replace(/[ \t]{2,}/g, ' ').trim()).join('\n')
    .replace(/^#{1,6}\s*/gm, '').replace(/\*\*(.+?)\*\*/g, '$1').replace(/^\s*[-*]\s+/gm, '• ').replace(/\|/g, ' ').replace(/\n{3,}/g, '\n\n').trim();
}

function painel() {
  if (!_painel) return '';
  const t = (_conv[_painel.t]?.trechos || []).find(x => x.n === _painel.n);
  if (!t) return '';
  return `<aside class="lq-painel" aria-label="Texto da norma">
    <div class="lq-p-h"><div><small>${esc(t.fonte.replace(/^Texto oficial:\s*/, 'Texto oficial · ').replace(/^Ficha do Laudomiro:\s*/, 'Ficha do Laudomiro · ').replace(/^Base de agentes do Laudomiro:\s*/, 'Ficha do agente · '))}</small><h4>${esc(t.rotulo)}</h4>${t.secao ? `<p>${esc(t.secao)}</p>` : ''}</div>
      <button type="button" class="lq-x" data-acao="campo:lq-fechar" aria-label="Fechar">${I.x}</button></div>
    <blockquote>${esc(limparMd(t.tipo === 'agente' ? fichaAgente(t.texto) : t.texto))}</blockquote>
    <div class="lq-p-m">Texto copiado da base do Laudomiro${t.tipo === 'oficial' ? ' (texto oficial)' : ''}. Toque em outro item da resposta para trocar.</div>
  </aside>`;
}

/* O trecho de agente é o JSON da base: mostra como texto corrido. */
function fichaAgente(json) {
  try {
    const a = JSON.parse(json);
    const lin = [];
    const add = (r, v) => { if (v != null && v !== '' && !(Array.isArray(v) && !v.length)) lin.push(`${r}: ${Array.isArray(v) ? v.join(', ') : typeof v === 'object' ? Object.entries(v).map(([k, x]) => `${k} ${x}`).join('; ') : v}`); };
    add('Agente', a.nome); add('Também chamado', a.sinonimos?.slice?.(0, 6));
    for (const [k, v] of Object.entries(a)) if (!['nome', 'sinonimos', 'id'].includes(k)) add(k.replace(/_/g, ' '), v);
    return lin.join('\n');
  } catch { return json; }
}


/* ══ v254 · ler FDS (FISPQ) e analisar foto — só consulta ══════════════════
   O arquivo vai para a função do servidor, é lido e descartado: no GRID fica
   só a resposta. A miniatura da foto existe só na memória desta tela.
   Liberado pelo servidor (status.anexos): hoje só o Provedor, até o teste. */
const TAM_PDF = 8 * 1024 * 1024, TAM_FOTO = 4 * 1024 * 1024, LADO_FOTO = 1600;
const PASSOS = {
  fds: ['Abrindo o PDF', 'Procurando a composição', 'Conferindo na base do GRID', 'Montando a resposta'],
  foto: ['Olhando a foto', 'Procurando os pontos de atenção', 'Conferindo nas NRs', 'Montando a resposta'],
};
const NOME_GHS = { GHS01: 'Explosivo', GHS02: 'Inflamável', GHS03: 'Oxidante', GHS04: 'Gás sob pressão', GHS05: 'Corrosivo', GHS06: 'Tóxico', GHS07: 'Irritante', GHS08: 'Perigo à saúde', GHS09: 'Meio ambiente' };
/* v256: por que o componente não tem dados da base (a base tem o Anexo 11 da NR-15 completo). */
const FORA = {
  sem_cas: 'A FDS não identifica este componente (sem CAS). Peça ao fornecedor o nome químico ou o número CAS.',
  fora_anexo11: 'Não consta na lista da NR-15 (Anexo 11). Veja se a atividade se enquadra no Anexo 13 e confira a ACGIH.',
  cas_invalido: 'O CAS desta FDS tem erro e não deu para conferir. Peça ao fornecedor o número correto.',
  x: 'Não está na base do GRID. Confira na NR-15 e na ACGIH.',
};
const GRAU_F = { 'mínimo': ['mínima', 'min'], 'médio': ['média', 'med'], 'máximo': ['máxima', 'max'] };

/* v255: no celular o campo focado mantinha o texto depois de enviar (o redesenho preserva o campo em foco). */
function limparCampo() { document.querySelectorAll('#lqTxt').forEach((el) => { el.value = ''; }); }

const anexosLigados = () => !!_status?.anexos && !semPermissao() && !!_status?.configurado;

function menuAnexo() {
  const op = (chave, ic, cor, titulo, sub, accept, extra = '', cls = '') =>
    `<label class="lq-mo${cls}"><input type="file" hidden accept="${accept}" ${extra} data-cp-foto="${chave}"><span class="ic ${cor}">${ic}</span><span><b>${titulo}</b><small>${sub}</small></span></label>`;
  return `<div class="lq-menu-fundo" data-acao="campo:lq-clip"></div>
  <div class="lq-menu" role="menu" aria-label="Anexar">
    <div class="lq-menu-h"><b>Anexar</b><button type="button" class="lq-x" data-acao="campo:lq-clip" aria-label="Fechar">${I.x}</button></div>
    ${op('lq.fds', IC.pdf, 'pdf', 'Ler uma FDS (FISPQ)', 'PDF do fornecedor, até 8 MB. Ele resume e cruza com a base do GRID.', 'application/pdf,.pdf')}
    ${op('lq.camera', IC.cam, 'img', 'Tirar foto agora', 'Abre a câmera do celular.', 'image/*', 'capture="environment"', ' so-cel')}
    ${op('lq.galeria', IC.img, 'img', 'Analisar uma foto', 'Escolha uma foto do ambiente. Ele aponta o que enxerga.', 'image/jpeg,image/png,image/webp,image/*')}
  </div>`;
}

function chipAnexo() {
  if (!_anexo) return '';
  const fds = _anexo.tipo === 'fds';
  return `<div class="lq-anx">${fds ? `<span class="ic pdf">${IC.pdf}</span>` : `<img class="lq-anx-img" src="${_anexo.thumb}" alt="">`}
    <div><b>${esc(_anexo.nome)}</b><small>${fds ? 'FDS em PDF' : 'Foto'} · ${tamanho(_anexo.tam)} · pronto para enviar</small></div>
    <button type="button" class="lq-x" data-acao="campo:lq-anx-tirar" aria-label="Tirar o anexo">${I.x}</button></div>`;
}

function tamanho(b) { return b >= 1048576 ? (b / 1048576).toFixed(1).replace('.', ',') + ' MB' : Math.max(1, Math.round(b / 1024)) + ' KB'; }

function lerComoBase64(arquivo) {
  return new Promise((ok, falha) => {
    const fr = new FileReader();
    fr.onload = () => ok(String(fr.result).split(',')[1] || '');
    fr.onerror = () => falha(new Error('Não consegui ler o arquivo.'));
    fr.readAsDataURL(arquivo);
  });
}

/* Foto reduzida no aparelho (lado maior 1600 px, JPEG): menos dados no 4G e menos custo. */
async function reduzirFoto(arquivo) {
  let img;
  try { img = await createImageBitmap(arquivo, { imageOrientation: 'from-image' }); }
  catch { throw new Error('Não consegui abrir esta foto. Tente uma foto em JPG ou PNG.'); }
  const desenhar = (lado, q) => {
    const k = Math.min(1, lado / Math.max(img.width, img.height));
    const c = document.createElement('canvas');
    c.width = Math.round(img.width * k); c.height = Math.round(img.height * k);
    c.getContext('2d').drawImage(img, 0, 0, c.width, c.height);
    return c.toDataURL('image/jpeg', q);
  };
  const grande = desenhar(LADO_FOTO, 0.85), mini = desenhar(480, 0.8);
  img.close?.();
  const base64 = grande.split(',')[1];
  return { base64, thumb: mini, tam: Math.floor(base64.length * 3 / 4) };
}

async function prepararArquivo(chave, arquivos) {
  const f = arquivos?.[0]; if (!f) return;
  _menuAnexo = false;
  try {
    if (chave === 'lq.fds') {
      if (!/pdf$/i.test(f.type) && !/\.pdf$/i.test(f.name)) throw new Error('A FDS precisa estar em PDF.');
      if (f.size > TAM_PDF) throw new Error('O PDF passa de 8 MB. Peça ao fornecedor uma versão menor.');
      const base64 = await lerComoBase64(f);
      if (!base64.startsWith('JVBER')) throw new Error('Este arquivo não é um PDF.');
      _anexo = { tipo: 'fds', nome: f.name || 'FDS.pdf', mime: 'application/pdf', base64, tam: f.size };
    } else {
      if (f.type && !/^image\//.test(f.type)) throw new Error('Escolha uma foto.');
      const r = await reduzirFoto(f);
      if (r.tam > TAM_FOTO) throw new Error('A foto ficou grande demais. Tente outra.');
      _anexo = { tipo: 'foto', nome: (f.name || 'foto').replace(/\.\w+$/, '') + '.jpg', mime: 'image/jpeg', ...r };
    }
  } catch (e) { avisar(e.message || 'Não consegui abrir o arquivo.', 'erro'); }
  repintar();
  setTimeout(() => { const el = [...document.querySelectorAll('#lqTxt')].find(x => x.getBoundingClientRect().width > 0); el?.focus?.(); }, 80);
}

async function enviarAnexo(p) {
  if (_conv.some(t => t.carregando)) return;
  if (semPermissao()) { avisar('Seu perfil de acesso não inclui o Laudomiro. Peça ao administrador.', 'erro'); return; }
  const a = _anexo; _anexo = null;
  const turno = { pergunta: p, anexo: { tipo: a.tipo, nome: a.nome, thumb: a.thumb || '' }, carregando: true, passo: 0, _arquivo: a };
  _ctx = null;  // a FDS nova (ou a foto) muda o assunto da conversa
  _conv.push(turno); _txt = ''; _painel = null; _copiarMenu = null; limparCampo();
  repintar(); rolarFim();
  const relogio = setInterval(() => { if (turno.passo < 3) { turno.passo++; repintar(); } }, 6000);
  try {
    const r = await chamar({ acao: 'anexo', tipo: a.tipo, arquivo: { nome: a.nome, mime: a.mime, base64: a.base64 }, pergunta: p || undefined });
    if (r.aviso) Object.assign(turno, { carregando: false, aviso: r.aviso });
    else {
      Object.assign(turno, { carregando: false, id: r.id, resposta: r.resposta, trechos: r.trechos || [], resumo: r.resumo || '', _arquivo: null });
      if (r.resposta?.tipo === 'fds') _ctx = { produto: r.resposta.titulo, contexto: r.resposta.contexto || r.resumo || '' };
      if (_status && r.restantes != null) _status.restantes = r.restantes;
      if (_status && r.id && r.gravado !== false) _status.recentes = [{ id: r.id, pergunta: `${a.tipo === 'fds' ? 'FDS' : 'Foto'}: ${a.nome}${p ? ' — ' + p : ''}`, tipo: a.tipo, criado_em: new Date().toISOString() }, ...(_status.recentes || [])].slice(0, 6);
    }
  } catch (e) {
    Object.assign(turno, { carregando: false, erro: e.message || 'O Laudomiro não conseguiu ler o arquivo.', podeRepetir: !['NAO_CONFIGURADO', 'COTA', 'SEM_PERMISSAO', 'ANEXO_BLOQUEADO'].includes(e.codigo) && e.status !== 400 && e.status !== 413 });
    if (e.codigo === 'ANEXO_BLOQUEADO' && _status) _status.anexos = false;
  } finally { clearInterval(relogio); }
  repintar(); rolarFim();
}

function carregandoAnexo(turno) {
  const ps = PASSOS[turno.anexo.tipo] || PASSOS.fds;
  return `<article class="lq-resp lq-carr" aria-live="polite"><span class="lq-seal p">${SEAL}</span><div>
    <b>${turno.anexo.tipo === 'fds' ? 'Lendo a FDS…' : 'Analisando a foto…'}</b>
    <div class="lq-passos">${ps.map((t, i) => `<div class="${i < turno.passo ? 'f' : i === turno.passo ? 'a' : ''}"><i>${i < turno.passo ? '✓' : i === turno.passo ? '…' : ''}</i>${t}</div>`).join('')}</div>
    <small>Pode levar até um minuto.</small></div></article>`;
}

function avisoAnexo(turno) {
  const a = turno.aviso, fds = a.tipo === 'fds';
  return `<article class="lq-resp"><div class="lq-ruim">${IC.erro}<div><b>${esc(a.titulo)}</b><p>${esc(a.texto)}</p>
    <p class="lq-ruim-c">Isto não gastou pergunta da cota.</p>
    ${anexosLigados() ? `<button type="button" class="btn btn-outline btn-sm" data-acao="campo:lq-clip">${fds ? 'Escolher outro arquivo' : 'Escolher outra foto'}</button>` : ''}</div></div></article>`;
}

const refChip = (r) => r ? `<span class="lq-ref">${esc(r)}</span>` : '';
const negritoInicio = (t) => esc(t).replace(/^(Sim\.|Não\.|Depende\.)/, '<b>$1</b>');

function tagsAgente(b) {
  const tags = [];
  if (b.grau) { const [f, c] = GRAU_F[b.grau] || [b.grau, 'med']; tags.push(`<span class="tag ${c}">${b.aproximado ? 'Possível: insalubridade ' : 'Insalubridade '}${esc(f)} ${b.pct}%</span>`); }
  else if (b.obs) tags.push(`<span class="tag no">${esc(b.obs.replace(/:.*$/, ''))}</span>`);
  const p = b.prev || {};
  if (p.status === 'sim') tags.push(`<span class="tag ap">Aposentadoria especial${p.anos ? ': ' + p.anos + ' anos' : ''}</span>`);
  else if (p.status === 'familia') tags.push('<span class="tag ap">Aposentadoria: depende do laudo</span>');
  else if (p.status === 'conferir') tags.push('<span class="tag ap">Aposentadoria: conferir</span>');
  else if (p.status === 'nao') tags.push('<span class="tag no">Sem aposentadoria especial</span>');
  const lin = [b.lt ? `Limite ${esc(b.lt)}${b.teto ? ' (teto)' : ''}` : '', b.pele ? 'absorve pela pele' : '', b.t24 ? `eSocial ${esc(b.t24)}` : '', b.aproximado ? 'composto do grupo: confira a ficha' : ''].filter(Boolean).join(' · ');
  return tags.join('') + (lin ? `<br>${lin}` : '');
}

function respostaFds(turno, tIdx) {
  const r = turno.resposta;
  const conf = (r.conferencia || []).map(c => `<span><em class="${c.ok ? 'ok' : 'nok'}">${c.ok ? '✓' : '!'}</em> ${esc(c.texto)}</span>`).join('');
  const comp = (r.composicao || []).map(c => `<div class="lq-sb${c.base ? '' : ' fora'}">
      <div class="nm"><b>${esc(c.nome)}</b><small>${c.cas ? 'CAS ' + esc(c.cas) : 'sem CAS'}${c.faixa ? ' · ' + esc(c.faixa) : ''}${c.casOk === false ? ' · <em class="nok">CAS com erro de digitação</em>' : ''}</small></div>
      <div class="bs">${c.base ? tagsAgente(c.base) : `<span class="cinza">${FORA[c.fora] || FORA.x}</span>`}</div>
      ${c.base && c.n ? `<button type="button" class="lk" data-acao="campo:lq-fonte:${tIdx}.${c.n}">Ver ficha</button>` : '<span></span>'}</div>`).join('');
  const partes = (r.partes || []).map((p, i) => {
    const aberta = turno.abertas ? turno.abertas.has(p.chave) : i === 0;
    return `<div><button type="button" class="h" data-acao="campo:lq-parte:${tIdx}.${p.chave}" aria-expanded="${aberta}">${esc(p.titulo)}<span><small>${esc(p.ref || '')}</small><i>${aberta ? '▴' : '▾'}</i></span></button>${aberta ? `<div class="c">${esc(p.texto)}</div>` : ''}</div>`;
  }).join('');
  return `<article class="lq-resp lq-fds">
    <header class="lq-ver"><span class="lq-selo v-fds">FDS</span><div><h3>${esc(r.titulo)}</h3>${r.subtitulo ? `<p>${esc(r.subtitulo)}</p>` : ''}</div></header>
    ${r.curta ? `<p class="lq-curta">${negritoInicio(r.curta)} ${refChip(r.curta_ref)}</p>` : ''}
    <div class="lq-res3">${(r.quadros || []).map(q => `<div class="lq-r"><small>${esc(q.rotulo)}</small><b>${esc(q.titulo)}</b>${q.texto ? `<span>${esc(q.texto)}</span>` : ''}${q.ref ? `<em class="ref">${esc(q.ref)}</em>` : ''}</div>`).join('')}</div>
    ${r.aviso_norma ? `<div class="lq-velha2">${IC.erro}<div><b>${(r.aviso_norma_tipo || (/^A revisão é de/.test(r.aviso_norma) ? 'antiga' : 'confirmar')) === 'antiga' ? 'FDS no modelo antigo.' : 'Confira a norma da FDS.'}</b> ${esc(r.aviso_norma)}</div></div>` : ''}
    ${(r.pictogramas || []).length || r.palavra ? `<div class="lq-sec"><h5>Pictogramas (seção 2)</h5><div class="ghs">${r.palavra ? `<span class="pal">${esc(r.palavra)}</span>` : ''}${(r.pictogramas || []).map(g => GHS[g] ? `<figure>${GHS[g]}<figcaption>${NOME_GHS[g]}</figcaption></figure>` : '').join('')}</div></div>` : ''}
    ${conf ? `<div class="lq-sec"><h5>Conferência da FDS</h5><div class="lq-conf2">${conf}</div></div>` : ''}
    ${comp ? `<div class="lq-sec"><h5>Composição${r.composicao_ref ? ' (' + esc(r.composicao_ref.toLowerCase()) + ')' : ''} e o que a base do GRID diz</h5><div class="lq-subs">${comp}</div></div>` : ''}
    ${partes ? `<div class="lq-acc">${partes}</div>` : ''}
    ${r.cuidado ? `<div class="lq-cuid">${IC.erro}<div><b>Cuidado:</b> ${esc(r.cuidado)}</div></div>` : ''}
    ${rodape(turno, tIdx, 'laudo')}
  </article>`;
}

function respostaFoto(turno, tIdx) {
  const r = turno.resposta, thumb = turno.anexo?.thumb;
  const marc = turno.marcados || new Set();
  const pontos = (r.pontos || []).map((p, i) => `<div class="lq-pt2"><span class="n">${i + 1}</span><div>
      <span class="gv ${p.gravidade === 'ALTA' ? 'alta' : 'med'}">${p.gravidade === 'ALTA' ? 'ALTA' : 'MÉDIA'}</span><b>${esc(p.titulo)}</b>
      ${p.agora ? `<p class="agora"><b>Agora:</b> ${esc(p.agora)}</p>` : ''}
      ${p.detalhe || p.nr ? `<p>${esc(p.detalhe || '')}${p.nr ? (p.n ? ` <button type="button" class="lq-it" data-acao="campo:lq-fonte:${tIdx}.${p.n}" title="Ver o texto da ${esc(p.nr)}">${esc(p.nr)}</button>` : ` <span class="lq-it so">${esc(p.nr)}</span>`) : ''}</p>` : ''}</div></div>`).join('');
  return `<article class="lq-resp lq-foto-r">
    <header class="lq-ver"><span class="lq-selo v-foto">FOTO</span><div><h3>${esc(r.titulo)}</h3>${r.subtitulo ? `<p>${esc(r.subtitulo)}</p>` : ''}</div></header>
    ${r.curta ? `<p class="lq-curta">${negritoInicio(r.curta)}</p>` : ''}
    <div class="lq-foto${pontos ? '' : ' so'}">${thumb ? `<button type="button" class="lq-thumb" data-acao="campo:lq-ampliar:${tIdx}" aria-label="Ampliar a foto"><img src="${thumb}" alt="Foto enviada"></button>` : '<div class="lq-thumb vazio">A foto não fica guardada no GRID</div>'}
      ${pontos ? `<div class="lq-pts">${pontos}</div>` : ''}</div>
    ${(r.pessoas || []).length ? `<div class="lq-pess"><h5>Quem aparece na foto</h5>${r.pessoas.map((p, i) => `<div><b>${i + 1}.</b> ${esc(p.onde || '')}${p.atividade ? ' · ' + esc(p.atividade) : ''}${(p.epi_faltando || []).length ? `<span class="falta">Sem: ${esc(p.epi_faltando.join(', '))}</span>` : ''}${(p.epi_visto || []).length ? `<span class="tem">Com: ${esc(p.epi_visto.join(', '))}</span>` : ''}</div>`).join('')}</div>` : ''}
    ${(r.conferir || []).length ? `<div class="lq-conf3"><h5>A foto não responde: confira no local</h5>${r.conferir.map((c, i) => `<button type="button" class="lq-ck${marc.has(i) ? ' on' : ''}" data-acao="campo:lq-conf:${tIdx}.${i}" aria-pressed="${marc.has(i)}"><i>${marc.has(i) ? '✓' : ''}</i>${esc(c)}</button>`).join('')}</div>` : ''}
    <div class="lq-limite">${I.info}<div><b>Só vale para o que aparece na foto.</b> ${esc(String(r.limite || '').replace(/^Só vale para o que aparece na foto\.\s*/, ''))}</div></div>
    ${rodape(turno, tIdx, 'inspeção')}
  </article>`;
}

function rodape(turno, tIdx, oQue) {
  const tipo = turno.resposta?.tipo;
  const ops = tipo === 'fds'
    ? [['pgr', 'Para o PGR (inventário)', 'Perigos, agentes e EPI'], ['os', 'Para a ordem de serviço', 'Riscos e cuidados para o trabalhador'], ['dds', 'Para o DDS', '5 minutos sobre o produto'], ['resp', 'Só a resposta', '']]
    : [['rel', 'Para o relatório de inspeção', 'Pontos, medidas e o que conferir'], ['resp', 'Só a lista', '']];
  const aberto = _copiarMenu === tIdx;
  return `<footer class="lq-acts">
    <span class="cp">${aberto ? `<div class="lq-copiar" role="menu">${ops.map(([k, t, s]) => `<button type="button" data-acao="campo:lq-copiar-como:${tIdx}.${k}">${t}${s ? `<small>${s}</small>` : ''}</button>`).join('')}</div>` : ''}
      <button type="button" class="${aberto ? 'on' : ''}" data-acao="campo:lq-copiar-menu:${tIdx}" aria-expanded="${aberto}">${IC.copiar}<span>Copiar para…</span></button></span>
    ${turno.id ? `<button type="button" class="${turno.nota === 'util' ? 'on' : ''}" data-acao="campo:lq-util:${tIdx}" aria-pressed="${turno.nota === 'util'}">${IC.util}<span>Útil</span></button>
    <button type="button" class="${turno.nota === 'erro' ? 'on' : ''}" data-acao="campo:lq-erro:${tIdx}">${IC.erro}<span>Tem erro</span></button>` : ''}
    <small>Indicação para o técnico. Não substitui ${oQue}.</small>
  </footer>`;
}

/* Textos do "Copiar para…": montados só com o que está na tela. */
function textoCopiar(turno, como) {
  const r = turno.resposta || {};
  if (r.tipo === 'foto') {
    const pts = (r.pontos || []).map((p, i) => `${i + 1}. [${p.gravidade === 'ALTA' ? 'ALTA' : 'MÉDIA'}] ${p.titulo}${p.agora ? ' — Agora: ' + p.agora : ''}${p.nr ? ' (' + p.nr + ')' : ''}`);
    if (como === 'resp') return [r.titulo, ...pts].join('\n');
    return [`Inspeção por foto${r.subtitulo ? ' — ' + r.subtitulo : ''}`, '', ...pts, '', (r.conferir || []).length ? 'Conferir no local:\n' + r.conferir.map(c => '• ' + c).join('\n') : '',
      '', 'Observação: ' + (r.limite || ''), 'Indicação do GRID (Laudomiro); não substitui inspeção no local.'].filter(x => x !== null).join('\n').replace(/\n{3,}/g, '\n\n').trim();
  }
  const q = r.quadros || [], partes = Object.fromEntries((r.partes || []).map(p => [p.chave, p.texto]));
  const pictos = (r.pictogramas || []).map(g => NOME_GHS[g]).filter(Boolean).join(', ');
  const agentes = (r.composicao || []).map(c => {
    const b = c.base;
    const dados = b ? [b.grau ? `insalubridade ${(GRAU_F[b.grau] || [b.grau])[0]} ${b.pct}% (NR-15 Anexo ${b.anexo})` : '', b.lt ? 'limite ' + b.lt : '', b.pele ? 'absorve pela pele' : '', b.t24 ? 'eSocial ' + b.t24 : ''].filter(Boolean).join(', ') : (FORA[c.fora] || FORA.x).replace(/\.$/, '').toLowerCase();
    return `• ${c.nome}${c.cas ? ' (CAS ' + c.cas + ')' : ''}${c.faixa ? ' ' + c.faixa : ''}: ${dados}`;
  });
  const prod = `${r.titulo}${r.subtitulo ? ' — ' + r.subtitulo : ''}`;
  if (como === 'pgr') return [`Produto: ${prod}`, `Perigos: ${[r.palavra, q[0]?.titulo, pictos].filter(Boolean).join(' · ')}`, 'Agentes químicos:', ...agentes,
    `EPI indicado na FDS: ${q[1]?.titulo || ''}${q[1]?.texto ? ', ' + q[1].texto : ''}`, '', 'Fonte: FDS do fornecedor e base de agentes do GRID. Insalubridade e aposentadoria dependem de avaliação no local.'].join('\n');
  if (como === 'os') return [`Ao usar ${r.titulo}:`, `• Riscos: ${q[0]?.titulo || ''}${q[0]?.texto ? ' (' + q[0].texto + ')' : ''}.`, `• Use: ${q[1]?.titulo || 'o EPI indicado pelo seu supervisor'}.`,
    partes.guardar ? `• Guarde assim: ${partes.guardar}` : '', partes.emergencia ? `• Em emergência: ${partes.emergencia}` : '', '• Em dúvida, fale com o técnico de segurança.'].filter(Boolean).join('\n');
  if (como === 'dds') return [`DDS — ${r.titulo} (5 minutos)`, `1. O que é: produto ${r.palavra ? 'com a palavra "' + r.palavra + '" no rótulo' : 'químico'}${pictos ? '; símbolos: ' + pictos : ''}.`,
    `2. O perigo: ${q[0]?.titulo || ''}.`, `3. Como se proteger: ${q[1]?.titulo || ''}.`, partes.guardar ? `4. Como guardar: ${partes.guardar}` : '', partes.emergencia ? `5. Se acontecer um acidente: ${partes.emergencia}` : '',
    'Pergunta para a equipe: onde fica a FDS deste produto no setor?'].filter(Boolean).join('\n');
  return [`${r.titulo}${r.subtitulo ? ' — ' + r.subtitulo : ''}`, r.curta, ...q.map(x => `${x.rotulo}: ${x.titulo}${x.texto ? ' (' + x.texto + ')' : ''}`), r.cuidado ? 'Cuidado: ' + r.cuidado : '',
    'Indicação do GRID (Laudomiro); não substitui laudo.'].filter(Boolean).join('\n');
}

function copiarComo(tIdx, como) {
  const t = _conv[tIdx]; if (!t?.resposta) return;
  _copiarMenu = null; repintar();
  navigator.clipboard?.writeText(textoCopiar(t, como)).then(() => avisar('Texto copiado.'), () => avisar('Não foi possível copiar neste aparelho.', 'erro'));
}

function ampliarFoto(tIdx) {
  const src = _conv[tIdx]?.anexo?.thumb; if (!src) return;
  ponte().abrirModal?.('Foto enviada', `<img src="${src}" alt="Foto enviada" style="width:100%;border-radius:10px;display:block">
    <p style="margin:10px 0 0;font-size:12.5px;color:var(--text-3)">A foto não fica guardada no GRID: some ao sair desta conversa.</p>`, '<button class="btn btn-outline" onclick="fecharModal()">Fechar</button>');
}

export async function render(params = {}) {
  if (params.id && L.porId?.(params.id)) _aba = 'fichas';
  // v252: pergunta feita no Início ("Pergunte ao Laudomiro") já chega enviada
  if (params.pergunta && !params.__lqEnviada) {
    params.__lqEnviada = 1; _aba = 'perguntar'; _painel = null;
    const p = String(params.pergunta);
    setTimeout(() => enviar(p), 30);
  }
  ponte().cabecalhoMobile?.(`<div class="mh-greeting">Avaliação de Campo</div><div class="mh-name">Laudomiro</div>`);
  if (_aba === 'fichas') {
    const html = await Fichas.render({ ...params, embutido: true });
    return `<div class="lq lq-na-ficha">${abas()}${html}</div>`;
  }
  ligarTela({
    digitar: (chave, valor) => { if (chave === 'lq.txt') _txt = valor; },
    enter: (chave, valor) => { if (chave === 'lq.enviar') { _txt = valor; enviar(); } },
    foto: (chave, arquivos) => (/^lq\./.test(chave) ? prepararArquivo(chave, arquivos) : undefined),  // v254: FDS e foto
  });
  if (!_status) carregarStatus();
  return `<div class="lq${_painel ? ' com-painel' : ''}${_conv.length ? ' em-conversa' : ''}">${abas()}
    <div class="lq-corpo"><div class="lq-col">${_conv.length ? conversa() : inicio()}</div>${painel()}</div></div>`;
}

async function enviar(texto) {
  const p = String(texto ?? (valorVisivel('#lqTxt') || _txt)).trim();
  if (_anexo && texto == null) { enviarAnexo(p); return; }  // v254
  if (p.length < 4) { avisar('Escreva a pergunta.', 'erro'); return; }
  if (_conv.some(t => t.carregando)) return;
  if (semPermissao()) { avisar('Seu perfil de acesso não inclui o Laudomiro. Peça ao administrador.', 'erro'); return; }
  if (_status && !_status.configurado) { avisar('O Laudomiro ainda está sendo configurado.', 'erro'); return; }
  const historico = _conv.filter(t => t.resposta).slice(-2).map(t => ({ pergunta: t.pergunta, resposta: t.resumo || '' }));
  const turno = { pergunta: p, carregando: true };
  _conv.push(turno); _txt = ''; _painel = null; limparCampo();
  repintar();
  rolarFim();
  try {
    const r = await chamar({ acao: 'perguntar', pergunta: p, historico, contexto: _ctx?.contexto || undefined });
    Object.assign(turno, { carregando: false, id: r.id, resposta: r.resposta, trechos: r.trechos || [], resumo: r.resumo || '' });
    if (_status && r.restantes != null) _status.restantes = r.restantes;
    if (_status && r.id && r.gravado !== false) _status.recentes = [{ id: r.id, pergunta: p, criado_em: new Date().toISOString() }, ...(_status.recentes || [])].slice(0, 6);
  } catch (e) {
    Object.assign(turno, { carregando: false, erro: e.message || 'O Laudomiro não respondeu.', podeRepetir: !['NAO_CONFIGURADO', 'COTA', 'SEM_PERMISSAO'].includes(e.codigo) });
    if (e.codigo === 'NAO_CONFIGURADO' && _status) _status.configurado = false;
    if (e.codigo === 'SEM_PERMISSAO' && _status) _status.permitido = false;
  }
  repintar();
  rolarFim();
}

function rolarFim() {
  setTimeout(() => {
    const el = [...document.querySelectorAll('.lq-fio')].find(c => c.getBoundingClientRect().width > 0);
    const ult = el?.lastElementChild; if (ult) ult.scrollIntoView({ block: 'start', behavior: 'smooth' });
  }, 60);
}

function copiar(i) {
  const t = _conv[i]; const r = t?.resposta; if (!r) return;
  const mapa = new Map((t.trechos || []).map(x => [x.n, x.rotulo]));
  const tira = (s) => String(s || '').replace(/\{\{(\d+)\}\}/g, (m, n) => (mapa.get(+n) ? `(${mapa.get(+n)})` : '')).replace(/\s{2,}/g, ' ').trim();
  const txt = [`${(VEREDITO[r.veredito] || VEREDITO.INFO)[0]}: ${r.titulo}`, r.subtitulo, '', ...r.resposta.map(tira), r.cuidado ? '\nCuidado: ' + tira(r.cuidado) : '',
    '', 'Fontes: ' + (t.trechos || []).filter(x => r.fontes?.includes(x.n)).map(x => x.rotulo).join('; '),
    'Indicação do GRID (Laudomiro); não substitui laudo nem LTCAT.'].filter(x => x !== undefined).join('\n');
  navigator.clipboard?.writeText(txt).then(() => avisar('Resposta copiada.'), () => avisar('Não foi possível copiar neste aparelho.', 'erro'));
}

async function avaliar(i, nota, comentario = '') {
  const t = _conv[i]; if (!t?.id) return;
  t.nota = nota; repintar();
  try { await chamar({ acao: 'avaliar', id: t.id, nota, comentario }); avisar(nota === 'util' ? 'Obrigado! Isso ajuda o Laudomiro a melhorar.' : 'Obrigado. O erro foi registrado para correção da base.'); }
  catch (e) { t.nota = null; repintar(); avisar(e.message, 'erro'); }
}

function pedirErro(i) {
  window.__lqErro = () => {
    const c = (document.getElementById('lqErroTxt')?.value || '').trim();
    window.fecharModal?.(); avaliar(i, 'erro', c);
  };
  ponte().abrirModal?.('O que está errado?',
    `<p style="margin:0 0 10px;font-size:13px;color:var(--text-2)">Conte em poucas palavras o que não confere (item, valor, norma). Não escreva nomes nem CPF.</p>
     <textarea id="lqErroTxt" rows="4" maxlength="1000" style="width:100%;font:inherit;font-size:14px;padding:10px;border:1px solid var(--border);border-radius:8px" placeholder="Ex.: o item citado foi revogado em 2025"></textarea>`,
    '<button class="btn btn-outline" onclick="fecharModal()">Cancelar</button><button class="btn btn-amber" onclick="window.__lqErro&&window.__lqErro()">Enviar</button>');
}

async function abrirRecente(id) {
  try {
    const r = await chamar({ acao: 'ver', id });
    const tipo = r.resposta?.tipo;
    if (tipo === 'fds' || tipo === 'foto') {
      // v254: conversa de FDS ou foto (o arquivo não fica guardado: volta só a resposta)
      const perg = String(r.pergunta || '').split(' — ').slice(1).join(' — ');
      _conv = [{ pergunta: perg, anexo: { tipo, nome: r.resposta.arquivo || '' }, id: r.id, resposta: r.resposta, trechos: r.trechos || [], nota: r.avaliacao || null,
        resumo: tipo === 'fds' ? (r.resposta.contexto || '') : r.resposta.titulo }];
      _ctx = tipo === 'fds' ? { produto: r.resposta.titulo, contexto: r.resposta.contexto || '' } : null;
    } else {
      _conv = [{ pergunta: r.pergunta, id: r.id, resposta: r.resposta, trechos: r.trechos || [], nota: r.avaliacao || null,
        resumo: [r.resposta?.titulo, ...(r.resposta?.resposta || [])].join(' ').replace(/\{\{\d+\}\}/g, '') }];
      _ctx = null;
    }
    _painel = null; _anexo = null; repintar();
  } catch (e) { avisar(e.message, 'erro'); }
}

export async function acao(nome, valor, redesenhar) {
  if (nome === 'campo:lq-pintar') { await redesenhar(); return true; }
  // v254: um clique em qualquer outra coisa fecha os menus abertos
  if (nome !== 'campo:lq-clip' && _menuAnexo) _menuAnexo = false;
  if (nome !== 'campo:lq-copiar-menu' && !/^campo:lq-copiar-como/.test(nome) && _copiarMenu != null) _copiarMenu = null;
  if (nome === 'campo:lq-clip') { _menuAnexo = !_menuAnexo; redesenhar(); return true; }
  if (nome === 'campo:lq-anx-tirar') { _anexo = null; redesenhar(); return true; }
  if (nome === 'campo:lq-ctx-sair') { _ctx = null; redesenhar(); return true; }
  if (nome === 'campo:lq-copiar-menu') { _copiarMenu = _copiarMenu === +valor ? null : +valor; redesenhar(); return true; }
  if (nome === 'campo:lq-copiar-como') { const [t, como] = String(valor).split('.'); copiarComo(+t, como); return true; }
  if (nome === 'campo:lq-parte') {
    const [t, ch] = String(valor).split('.'); const tu = _conv[+t]; if (!tu) return true;
    if (!tu.abertas) tu.abertas = new Set([(tu.resposta?.partes || [])[0]?.chave].filter(Boolean));
    tu.abertas.has(ch) ? tu.abertas.delete(ch) : tu.abertas.add(ch); redesenhar(); return true;
  }
  if (nome === 'campo:lq-conf') {
    const [t, i] = String(valor).split('.').map(Number); const tu = _conv[t]; if (!tu) return true;
    tu.marcados ||= new Set(); tu.marcados.has(i) ? tu.marcados.delete(i) : tu.marcados.add(i); redesenhar(); return true;
  }
  if (nome === 'campo:lq-ampliar') { ampliarFoto(+valor); return true; }
  if (nome === 'campo:lq-aba') { _aba = valor === 'fichas' ? 'fichas' : 'perguntar'; _painel = null; redesenhar(); window.scrollTo?.(0, 0); return true; }
  if (_aba === 'fichas') return Fichas.acao(nome, valor, redesenhar);
  if (nome === 'campo:lq-enviar') { enviar(); return true; }
  if (nome === 'campo:lq-sug') { const s = SUGESTOES[+valor]; if (s) enviar(s[1]); return true; }
  if (nome === 'campo:lq-nova') { _conv = []; _painel = null; _txt = ''; _ctx = null; _anexo = null; redesenhar(); return true; }
  if (nome === 'campo:lq-fonte') { const [t, n] = String(valor).split('.').map(Number); _painel = (_painel && _painel.t === t && _painel.n === n) ? null : { t, n }; redesenhar(); return true; }
  if (nome === 'campo:lq-fechar') { _painel = null; redesenhar(); return true; }
  if (nome === 'campo:lq-copiar') { copiar(+valor); return true; }
  if (nome === 'campo:lq-util') { avaliar(+valor, 'util'); return true; }
  if (nome === 'campo:lq-erro') { pedirErro(+valor); return true; }
  if (nome === 'campo:lq-abrir') { abrirRecente(valor); return true; }
  if (nome === 'campo:lq-repetir') {
    const t = _conv[+valor]; if (!t) return true;
    _conv.splice(+valor, 1);
    if (t._arquivo) { _anexo = t._arquivo; enviarAnexo(t.pergunta); } else enviar(t.pergunta);  // v254: repete com o mesmo arquivo
    return true;
  }
  return false;
}

/* A rota antiga "Consultar agente" (campo-agentes) abre esta mesma tela na aba Fichas. */
export const comoFichas = {
  render: (params = {}) => { if (!params.__lq) { params.__lq = 1; _aba = 'fichas'; } return render(params); },
  acao,
};
